using System;using System.IO;using UnityEditor;using UnityEditor.Build.Reporting;using UnityEngine;
public static class ReleaseBuildChecks {public static void Run(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-releaseOutput");if(i<0)throw new Exception("Explicit local output required");string folder=Path.GetFullPath(args[i+1]);if(folder.StartsWith(Path.GetFullPath(Application.dataPath),StringComparison.OrdinalIgnoreCase))throw new Exception("Output must be outside Assets");Directory.CreateDirectory(folder);var r=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/Shioka/Scenes/CombatFormulaComparison.unity"},locationPathName=Path.Combine(folder,"Shioka.exe"),target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});Debug.Log("RELEASE_BUILD "+r.summary.result+" errors="+r.summary.totalErrors+" bytes="+r.summary.totalSize);if(r.summary.result!=BuildResult.Succeeded)throw new Exception("Local release build failed");}}
